/* How a price was made, and a creator's own dollar price for the marketplace (currency round AM). Storelib's marketplace (Explore, creator pages, product pages on Storelib, communities) shows and charges US dollars once the switch MARKETPLACE_USD is on for a store; a store's website, OnePage and shared checkout links keep its own currency. Each order now notes where its price came from: `pricing_context` (merchant or marketplace), the store's own price and currency (`list_currency`, `list_amount_cents`), and for a marketplace dollar price its source (`price_source`: converted at the ECB rate, or the creator's own approved dollar price) and the rate day and rate behind it (`fx_as_of`, `fx_rate`). The order's own `currency` and amounts stay as charged. Products and their options get `marketplace_usd_cents` with `marketplace_usd_approved_at`: a dollar price the creator set themselves, used only once they approved it. Columns only, all nullable, with checks; no row changes, no amount moves. The code writes them as a separate update that may fail, so orders are made the same before and after this runs. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.orders') IS NULL THEN RAISE NOTICE 'marketplace pricing: no orders table yet.'; RETURN; END IF; ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS pricing_context text, ADD COLUMN IF NOT EXISTS list_currency text, ADD COLUMN IF NOT EXISTS list_amount_cents bigint, ADD COLUMN IF NOT EXISTS price_source text, ADD COLUMN IF NOT EXISTS fx_as_of date, ADD COLUMN IF NOT EXISTS fx_rate numeric(20,10); IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'orders_pricing_context_check' AND conrelid = 'public.orders'::regclass) THEN ALTER TABLE public.orders ADD CONSTRAINT orders_pricing_context_check CHECK (pricing_context IS NULL OR pricing_context IN ('merchant', 'marketplace')) NOT VALID; END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'orders_price_source_check' AND conrelid = 'public.orders'::regclass) THEN ALTER TABLE public.orders ADD CONSTRAINT orders_price_source_check CHECK (price_source IS NULL OR price_source IN ('native', 'fixed', 'converted')) NOT VALID; END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'orders_list_amount_check' AND conrelid = 'public.orders'::regclass) THEN ALTER TABLE public.orders ADD CONSTRAINT orders_list_amount_check CHECK ((list_amount_cents IS NULL OR list_amount_cents >= 0) AND (list_currency IS NULL OR list_currency ~ '^[a-z]{3}$') AND (fx_rate IS NULL OR fx_rate > 0)) NOT VALID; END IF; END $do$;
DO $do$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['products', 'product_variants'] LOOP IF to_regclass('public.' || t) IS NULL THEN CONTINUE; END IF; EXECUTE format('ALTER TABLE public.%I ADD COLUMN IF NOT EXISTS marketplace_usd_cents integer, ADD COLUMN IF NOT EXISTS marketplace_usd_approved_at timestamptz', t); IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = t || '_marketplace_usd_check' AND conrelid = ('public.' || t)::regclass) THEN EXECUTE format('ALTER TABLE public.%I ADD CONSTRAINT %I CHECK (marketplace_usd_cents IS NULL OR (marketplace_usd_cents >= 0 AND marketplace_usd_cents <= 100000000)) NOT VALID', t, t || '_marketplace_usd_check'); END IF; END LOOP; END $do$;
notify pgrst, 'reload schema';
